Rules.InvariantScript:
With(
    {
        // 0. Capture Context to prevent scoping errors
        _CurrentParentID: ThisItem.Id 
    },
    With(
        {
            // 1. Define the Pool of valid Child items
            // We use Value() and Coalesce() to ensure numeric comparison works safely
            _ChildPool: Filter(
                colSelectedConratctWithDevCoCosts,
                ParentId = _CurrentParentID, 
                Level = 3,
                Coalesce(Value(TotalCost), 0) > 0
            )
        },
        With(
            {
                // 2. Count "Selectable" (Not Used by others)
                _AvailableCount: CountRows(Filter(_ChildPool, !Used)),

                // 3. Count "Selected" (Selected AND Not Used)
                _SelectedCount: CountRows(Filter(_ChildPool, Selected && !Used)),

                // Colors
                _ColorPrimary: "#0078D4",
                _ColorWhite: "#FFFFFF",
                _ColorGrey: "#605E5C",
                _ColorDisabledFill: "#C8C6C4",
                _ColorDisabledText: "#FFFFFF"
            },

            // 4. Determine State
            With(
                {
                    _State: If(
                        // If nothing can be selected (locked or empty), show LOCKED
                        _AvailableCount = 0, "LOCKED",
                        // If nothing selected, show UNCHECKED
                        _SelectedCount = 0, "UNCHECKED",
                        // If everything available is selected, show CHECKED
                        _SelectedCount = _AvailableCount, "CHECKED",
                        // Otherwise (some selected), show PARTIAL
                        "PARTIAL"
                    )
                },

                // 5. Render SVG
                "data:image/svg+xml;utf8, " & EncodeUrl(
                    "<svg width='24' height='24' viewBox='0 0 24 24' xmlns='http://www.w3.org/2000/svg'>" &
                    Switch(
                        _State,

                        "LOCKED", 
                        "<rect x='1' y='1' width='22' height='22' rx='2' ry='2' fill='" & _ColorDisabledFill & "'/>
                         " & If(CountRows(_ChildPool) > 0, "<path d='M6 12 L10 16 L18 8' stroke='" & _ColorDisabledText & "' stroke-width='2' fill='none' stroke-linecap='round' stroke-linejoin='round'/>", ""),

                        "UNCHECKED", 
                        "<rect x='1' y='1' width='22' height='22' rx='2' ry='2' fill='none' stroke='" & _ColorGrey & "' stroke-width='1.5'/>",

                        "CHECKED", 
                        "<rect x='1' y='1' width='22' height='22' rx='2' ry='2' fill='" & _ColorPrimary & "'/>
                         <path d='M6 12 L10 16 L18 8' stroke='" & _ColorWhite & "' stroke-width='2' fill='none' stroke-linecap='round' stroke-linejoin='round'/>",

                        "PARTIAL", 
                        "<rect x='1' y='1' width='22' height='22' rx='2' ry='2' fill='" & _ColorPrimary & "'/>
                         <line x1='6' y1='12' x2='18' y2='12' stroke='" & _ColorWhite & "' stroke-width='2' stroke-linecap='round'/>"
                    ) & 
                    "</svg>"
                )
            )
        )
    )
)

// 1. Define the pool of items we are allowed to change
With(
    {
        TargetChildren: Filter(
            colSelectedConratctWithDevCoCosts,
            ParentId = ThisItem.Id,
            Level = 3,
            TotalCost > 0,
            Used = false // We can only touch items not used by others
        )
    },
    // 2. Toggle Logic
    If(
        // LOGIC: If currently Unchecked (0 Selected), turn ON.
        // If currently Partial or Full (Count > 0), turn OFF.
        CountRows(Filter(TargetChildren, Selected)) = 0,
        
        // ACTION: Select All
        UpdateIf(
            colSelectedConratctWithDevCoCosts,
            Id in TargetChildren.Id,
            {Selected: true}
        ),

        // ACTION: Deselect All (Visual effect: Partial -> Empty, Full -> Empty)
        UpdateIf(
            colSelectedConratctWithDevCoCosts,
            Id in TargetChildren.Id,
            {Selected: false}
        )
    )
);

